c341ea673519366a9d20ef8"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"appflowy"}}},"problem_id":{"$ref":{"table":"problems","where":{"slug":"vendor-lock-in"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:40ffb997da500aec62bffacd94ca2d24478872009fa479480b03837d167aeefb"}}}}]},{"table":"product_audience_evidence","operation":"upsert","conflictColumns":["product_id","audience_id","claim_evidence_id"],"rows":[{"product_id":{"$ref":{"table":"products","where":{"slug":"affine"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"data-ownership-seekers"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:52a5b76521e84a445c7194c24798f51b852625844d96770f42ebd2e0ca864492"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"affine"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"offline-first-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:3714cff64c31063c4a871b078f5a89ea6c9c59be40f07a65529f2d82acf4ec5c"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"affine"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"privacy-conscious-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:4aef4a83c7929b1caa31a14c042574ba66db0de9a2a15969df4ae16326579740"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"anytype"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"data-ownership-seekers"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:5963ffd53ec0820502ec9f635ad453b8bdb7106a98b044fb4577dbceb59f5df5"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"anytype"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"offline-first-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:11362ed241a116bfa3753d39f9f43ca4682740cdbf4d94a959d1b56fe3153635"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"anytype"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"privacy-conscious-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:5b120b51acd3206600c3c448b02c7b9cef3cdfb5ba6dc804c8ebe432a596957b"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"appflowy"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"data-ownership-seekers"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:2101969ea5974385f2e3eea5301359786008df1bb97335ad413a470630cd9dcf"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"appflowy"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"offline-first-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:89d8ef318cb205adea37621f45bc71ca7e4d466ccafedef321cc7b020745daec"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"appflowy"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"privacy-conscious-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:d56a560f15146ef96a1c28ee03341455095b2f29494565a85450dfd9b652e31e"}}}}]},{"table":"escape_routes","operation":"upsert","conflictColumns":["slug"],"rows":[]},{"table":"escape_route_products","operation":"upsert","conflictColumns":["escape_route_id","product_id"],"rows":[]}],"route":{"slug":"offline-notion-alternatives","name":"Offline Notion Alternatives","description":"Personal offline notes and locally available organized content in installed native workspaces. Compare AFFiNE desktop documents and whiteboards, Anytype local objects, and AppFlowy native offline mode. Notion also supports prepared offline pages in desktop/mobile apps. Cloud sync, hosted imports, remote attachments and collaboration have separate requirements. This does not guarantee complete Notion parity or full cloud-content availability offline.","anchor_id":{"$ref":{"table":"anchors","where":{"slug":"notion"}}},"last_verified_at":"2026-10-08T00:00:00Z"},"priorRoute":{"slug":"offline-notion-alternatives","name":"Offline Notion Alternatives","description":"Qualification: an evidence-backed Notion alternative relationship AND works-offline=true with verified evidence. A likely anchor relationship remains an explicitly provisional draft candidate. Missing anchor evidence or only likely offline evidence means unknown, not false.","anchor_id":{"$ref":{"table":"anchors","where":{"slug":"notion"}}},"status":"draft","editorially_approved":false,"last_verified_at":"2026-10-06T00:00:00Z"},"priorMembers":[{"escape_route_id":{"$ref":{"table":"escape_routes","where":{"slug":"offline-notion-alternatives"}}},"product_id":{"$ref":{"table":"products","where":{"slug":"affine"}}},"position":2,"editorial_note":"Official download page explicitly says the desktop app works fully offline."},{"escape_route_id":{"$ref":{"table":"escape_routes","where":{"slug":"offline-notion-alternatives"}}},"product_id":{"$ref":{"table":"products","where":{"slug":"appflowy"}}},"position":3,"editorial_note":"Official docs explicitly support offline mode."},{"escape_route_id":{"$ref":{"table":"escape_routes","where":{"slug":"offline-notion-alternatives"}}},"product_id":{"$ref":{"table":"products","where":{"slug":"obsidian"}}},"position":1,"editorial_note":"Verified offline support; Notion alternative relationship remains likely from existing third-party evidence. Provisional draft candidate only."}],"members":[{"productSlug":"affine","position":1,"noveltyScore":0,"editorialNote":"Personal offline note and object organization only. Native desktop local documents, databases and whiteboards after installation. Cloud synchronization needs connectivity; mobile and browser parity are not established. No guarantee of full Notion feature, team or migration parity."},{"productSlug":"anytype","position":2,"noveltyScore":0,"editorialNote":"Personal offline note and object organization only. Anytype local-first personal spaces after initial setup; synchronization and Notion import need connectivity. No guarantee of full Notion feature, team or migration parity. Local-only is a separate experimental mode with manual backup responsibility."},{"productSlug":"appflowy","position":3,"noveltyScore":0,"editorialNote":"Personal offline note and object organization only. Locally available content in the installed native workspace after setup. Cloud synchronization and the documented hosted Notion import need connectivity; complete offline caching of Cloud pages and attachments is not established. No guarantee of full Notion feature, team or migration parity."}]}$pr513_data$::jsonb;
 tbl jsonb; item jsonb; wanted jsonb; prop record; ref_where record;
 ref_id uuid; matched boolean; actual_count integer; expected_count integer;
 target_id uuid; route_id uuid; product_slug text; page jsonb;
BEGIN
 SET LOCAL lock_timeout='10s';
 PERFORM pg_advisory_xact_lock(7232003);
 LOCK TABLE software_discovery.evidence_sources, software_discovery.anchors, software_discovery.attributes, software_discovery.problems, software_discovery.audiences, software_discovery.products, software_discovery.product_attributes, software_discovery.product_anchors, software_discovery.product_problems, software_discovery.product_audiences, software_discovery.claim_evidence, software_discovery.product_attribute_evidence, software_discovery.product_anchor_evidence, software_discovery.product_problem_evidence, software_discovery.product_audience_evidence, software_discovery.escape_routes, software_discovery.escape_route_products IN SHARE ROW EXCLUSIVE MODE;
 IF (SELECT count(*) FROM software_discovery.products WHERE slug IN ('obsidian','things','omnifocus','2do') AND status='published')<>4 OR NOT EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug='todoist-alternatives-with-a-one-time-purchase' AND status='published' AND editorially_approved) THEN RAISE EXCEPTION 'PR5.13 prior published state mismatch'; END IF;
 IF (SELECT count(*) FROM software_discovery.products WHERE slug IN ('affine','anytype','appflowy') AND status IN ('draft','published'))<>3 THEN RAISE EXCEPTION 'PR5.13 target lifecycle mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM software_discovery.escape_route_products m JOIN software_discovery.escape_routes r ON r.id=m.escape_route_id JOIN software_discovery.products p ON p.id=m.product_id WHERE p.slug IN ('affine','anytype','appflowy') AND r.slug<>'offline-notion-alternatives' AND r.status='published' AND r.editorially_approved) THEN RAISE EXCEPTION 'PR5.13 other approved route exposure requires review'; END IF;
 FOR tbl IN SELECT value FROM jsonb_array_elements(payload->'tables') LOOP
  FOR item IN SELECT value FROM jsonb_array_elements(tbl->'rows') LOOP
   wanted=item;
   FOR prop IN SELECT key,value FROM jsonb_each(item) LOOP
    IF prop.value ? '$ref' THEN
     SELECT key,value INTO STRICT ref_where FROM jsonb_each(prop.value->'$ref'->'where');
     ref_id=NULL;
     EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',prop.value->'$ref'->>'table',ref_where.key) INTO ref_id USING ref_where.value #>> '{}';
     IF ref_id IS NULL THEN RAISE EXCEPTION 'PR5.13 required reference missing'; END IF;
     wanted=jsonb_set(wanted,ARRAY[prop.key],to_jsonb(ref_id));
    END IF;
   END LOOP;
   IF tbl->>'table'='products' THEN wanted=wanted-'status'; END IF;
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I c WHERE NOT EXISTS(SELECT 1 FROM jsonb_object_keys($1) k WHERE to_jsonb(c)->k IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::software_discovery.%I,$1))->k))',tbl->>'table',tbl->>'table') INTO matched USING wanted;
   IF NOT matched THEN RAISE EXCEPTION 'PR5.13 review mismatch: %',tbl->>'table'; END IF;
  END LOOP;
  IF left(tbl->>'table',8)='product_' THEN
   FOREACH product_slug IN ARRAY ARRAY['affine','anytype','appflowy'] LOOP
    SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=product_slug;
    SELECT count(*) INTO expected_count FROM jsonb_array_elements(tbl->'rows') r WHERE r->'product_id'->'$ref'->'where'->>'slug'=product_slug;
    EXECUTE format('SELECT count(*) FROM software_discovery.%I WHERE product_id=$1',tbl->>'table') INTO actual_count USING target_id;
    IF actual_count<>expected_count THEN RAISE EXCEPTION 'PR5.13 relationship/evidence set changed: %/%',product_slug,tbl->>'table'; END IF;
   END LOOP;
  END IF;
 END LOOP;
 SELECT id INTO STRICT ref_id FROM software_discovery.anchors WHERE slug='notion';
 wanted=jsonb_set(payload->'route',ARRAY['anchor_id'],to_jsonb(ref_id));
 SELECT id INTO route_id FROM software_discovery.escape_routes WHERE slug='offline-notion-alternatives';
 IF route_id IS NOT NULL THEN
  SELECT EXISTS(SELECT 1 FROM software_discovery.escape_routes c WHERE c.id=route_id AND ((status='draft' AND NOT editorially_approved) OR (status='published' AND editorially_approved)) AND NOT EXISTS(SELECT 1 FROM jsonb_object_keys(wanted) k WHERE to_jsonb(c)->k IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::software_discovery.escape_routes,wanted))->k)) INTO matched;
  IF NOT matched THEN
   IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_routes c WHERE c.id=route_id AND c.status='draft' AND NOT c.editorially_approved AND c.name=payload->'priorRoute'->>'name' AND c.description=payload->'priorRoute'->>'description' AND c.anchor_id=ref_id AND c.last_verified_at=(payload->'priorRoute'->>'last_verified_at')::timestamptz) THEN RAISE EXCEPTION 'PR5.13 route metadata/approval mismatch'; END IF;
   SELECT count(*) INTO actual_count FROM software_discovery.escape_route_products WHERE escape_route_id=route_id;
   IF actual_count<>jsonb_array_length(payload->'priorMembers') THEN RAISE EXCEPTION 'PR5.13 baseline membership drift'; END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(payload->'priorMembers') LOOP
    SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=item->'product_id'->'$ref'->'where'->>'slug';
    IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_route_products m WHERE escape_route_id=route_id AND product_id=target_id AND position IS NOT DISTINCT FROM (item->>'position')::integer AND novelty_score IS NOT DISTINCT FROM (item->>'novelty_score')::numeric AND relevance_score IS NOT DISTINCT FROM (item->>'relevance_score')::numeric AND constraint_fit_score IS NOT DISTINCT FROM (item->>'constraint_fit_score')::numeric AND quality_score IS NOT DISTINCT FROM (item->>'quality_score')::numeric AND editorial_note IS NOT DISTINCT FROM item->>'editorial_note') THEN RAISE EXCEPTION 'PR5.13 baseline member drift'; END IF;
   END LOOP;
   DELETE FROM software_discovery.escape_route_products WHERE escape_route_id=route_id;
   UPDATE software_discovery.escape_routes SET description=wanted->>'description',last_verified_at=(wanted->>'last_verified_at')::timestamptz,updated_at=now() WHERE id=route_id;
  END IF;
  SELECT count(*) INTO actual_count FROM software_discovery.escape_route_products WHERE escape_route_id=route_id;
  IF actual_count NOT IN (0,3) THEN RAISE EXCEPTION 'PR5.13 route membership drift'; END IF;
  IF actual_count=3 THEN
   FOR item IN SELECT value FROM jsonb_array_elements(payload->'members') LOOP
    SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=item->>'productSlug';
    IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_route_products m WHERE escape_route_id=route_id AND product_id=target_id AND position=(item->>'position')::integer AND novelty_score=0 AND relevance_score IS NULL AND constraint_fit_score IS NULL AND quality_score IS NULL AND editorial_note=item->>'editorialNote') THEN RAISE EXCEPTION 'PR5.13 member data mismatch'; END IF;
   END LOOP;
  END IF;
 ELSE
  IF payload->'priorRoute' IS NOT NULL THEN RAISE EXCEPTION 'PR5.13 baseline route missing'; END IF;
  INSERT INTO software_discovery.escape_routes(slug,name,description,anchor_id,last_verified_at) SELECT slug,name,description,anchor_id,last_verified_at FROM jsonb_populate_record(NULL::software_discovery.escape_routes,wanted) RETURNING id INTO route_id;
 END IF;
 UPDATE software_discovery.products SET status='published',updated_at=now() WHERE slug IN ('affine','anytype','appflowy') AND status='draft';
 FOR item IN SELECT value FROM jsonb_array_elements(payload->'members') LOOP
  SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=item->>'productSlug';
  INSERT INTO software_discovery.escape_route_products(escape_route_id,product_id,position,novelty_score,editorial_note) VALUES(route_id,target_id,(item->>'position')::integer,0,item->>'editorialNote') ON CONFLICT(escape_route_id,product_id) DO NOTHING;
 END LOOP;
 UPDATE software_discovery.escape_routes SET status='published',editorially_approved=true,updated_at=now() WHERE id=route_id AND status='draft' AND NOT editorially_approved;
 FOREACH product_slug IN ARRAY ARRAY['affine','anytype','appflowy'] LOOP
  page=software_discovery.product_discovery_page(product_slug);
  IF page IS NULL OR page->>'status'<>'published' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(page->'anchors') a WHERE a->>'slug'='notion' AND a->>'scope'='personal-offline-note-object-organization' AND a->>'verificationStatus'='verified') THEN RAISE EXCEPTION 'PR5.13 public projection failed'; END IF;
 END LOOP;
 RAISE SQLSTATE 'ZP513' USING MESSAGE='Rehearsal only';
EXCEPTION WHEN SQLSTATE 'ZP513' THEN RAISE NOTICE 'PR5.13 rehearsal rolled back; no publication persisted';
END $pr513$;
